	f := osptest.Start(t, &osptest.Fake{VTs: map[string]osptest.VT{
		"1.1": {Name: "BlueKeep", Family: "Windows", QoD: 97, QoDType: "remote_active", CVEs: []string{"CVE-2019-0708"}, CVSSv2: "AV:N/AC:L/Au:N/C:C/I:C/A:C", Solution: "Patch"},
